function ai_drawBookBook1(container, cb) {
    const dpr = window.devicePixelRatio || 1;
    const logicalWidth = 640;
    const padding = 40;
    const fontSize = 32;
    const unit = 1;
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    function updateBounds(x, y, r = 0) {
      minX = Math.min(minX, x - r);
      maxX = Math.max(maxX, x + r);
      minY = Math.min(minY, y - r);
      maxY = Math.max(maxY, y + r);
    }
    function updateTextBounds(text, x, y, align = 'center') {
        const estCharWidth = fontSize * 0.6;
        const width = text.length * estCharWidth;
        if (align === 'left') updateBounds(x + width, y, 0);
        else if (align === 'right') updateBounds(x - width, y, 0);
        else { updateBounds(x - width/2, y, 0); updateBounds(x + width/2, y, 0); }
        updateBounds(x, y - fontSize, 0);
        updateBounds(x, y + fontSize/3, 0);
    }
    const bookW = 180;
    const bookH = 260;
    const centerX = logicalWidth / 2;
    const centerY = bookH / 2 + padding;
    const bookLeft = centerX - bookW / 2;
    const bookRight = centerX + bookW / 2;
    const bookTop = centerY - bookH / 2;
    const bookBottom = centerY + bookH / 2;
    updateBounds(bookLeft, bookTop, 0);
    updateBounds(bookRight + 12, bookBottom + 12, 0);
    const lineY = bookBottom + 50;
    updateBounds(bookLeft, lineY + 8, 0);
    updateBounds(bookRight, lineY + 8, 0);
    updateTextBounds("18 厘米", centerX, lineY - 15, "center");
    if (minX === Infinity) { minX = 0; maxX = 640; minY = 0; maxY = 300; }
    const contentW = maxX - minX;
    const contentH = maxY - minY;
    const maxSafeW = logicalWidth - padding * 2;
    let safeScale = 1;
    if (contentW > maxSafeW) { safeScale = maxSafeW / contentW; }
    const finalHeight = (contentH * safeScale) + padding * 2;
    const wrapper = document.createElement('div');
    wrapper.style.display = 'flex';
    wrapper.style.flexDirection = 'column';
    wrapper.style.alignItems = 'center';
    wrapper.style.width = '100%';
    const cvs = document.createElement('canvas');
    cvs.style.width = '100%';
    cvs.style.height = 'auto';
    cvs.width = logicalWidth * dpr;
    cvs.height = finalHeight * dpr;
    wrapper.appendChild(cvs);
    container.appendChild(wrapper);
    const ctx = cvs.getContext('2d');
    ctx.scale(dpr, dpr);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    const offsetX = (logicalWidth - contentW * safeScale) / 2 - minX * safeScale;
    const offsetY = padding - minY * safeScale;
    ctx.translate(offsetX, offsetY);
    ctx.scale(safeScale, safeScale);
    ctx.fillStyle = '#FFFFFF';
    ctx.strokeStyle = '#2C3E50';
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.rect(bookLeft + 12, bookTop + 12, bookW, bookH);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = 'rgba(72, 219, 251, 0.2)';
    ctx.beginPath();
    ctx.rect(bookLeft, bookTop, bookW, bookH);
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(bookLeft + 25, bookTop);
    ctx.lineTo(bookLeft + 25, bookBottom);
    ctx.lineWidth = 4;
    ctx.stroke();
    ctx.fillStyle = '#2C3E50';
    ctx.font = 'bold 44px "Times New Roman"';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText("物 理", centerX + 12, centerY);
    ctx.strokeStyle = '#FF6B6B';
    ctx.fillStyle = '#FF6B6B';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(bookLeft, lineY);
    ctx.lineTo(bookRight, lineY);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(bookLeft + 15, lineY - 8);
    ctx.lineTo(bookLeft, lineY);
    ctx.lineTo(bookLeft + 15, lineY + 8);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(bookRight - 15, lineY - 8);
    ctx.lineTo(bookRight, lineY);
    ctx.lineTo(bookRight - 15, lineY + 8);
    ctx.stroke();
    ctx.font = `italic ${fontSize}px "Times New Roman"`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'bottom';
    ctx.fillText("18 厘米", centerX, lineY - 15);
    if (typeof cb === 'function') cb();
}
